-- C-04: customer/supplier masters and multi-subsidiary withholding rules.
set local lock_timeout='5s';set local statement_timeout='60s';
create schema entity_master_private;revoke all on schema entity_master_private from public,anon,authenticated,service_role;grant usage on schema entity_master_private to authenticated;
create function entity_master_private.meta(k text)returns table(t text,pk text,curtable text,fields text[])language sql immutable set search_path=pg_catalog as $$select c.t,c.pk,c.curtable,c.fields from(values
 ('customers','customers','customer_id','customer_currencies',array['company_name','tax_id','country_id','email','phone','is_intercompany','sales_representative_id','department_id','payment_term_id','envio_estado_cuenta_auto','credit_limit','applies_withholding','address','comments','customer_type']),
 ('suppliers','suppliers','supplier_id','supplier_currencies',array['company_name','tax_id','payment_id_type','payment_beneficiary_name','payment_bank_id','payment_iban','email','phone','is_intercompany','payment_term_id','applies_withholding','address','comments','supplier_type']))c(k,t,pk,curtable,fields)where c.k=$1$$;
create function entity_master_private.identity()returns bigint language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$declare sid bigint:=asset_posting_private.identity();begin if not exists(select 1 from public.users u join public.user_roles ur using(user_id)where u.user_id=public.app_user_id()and u.is_active and ur.role_id=public.app_active_role_id())or not exists(select 1 from public.subsidiaries where subsidiary_id=sid and is_active)then raise exception using errcode='42501',message='Seleccione usuario, rol y subsidiaria activos.';end if;return sid;end$$;
create function entity_master_private.allowed(k text,a text)returns boolean language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$begin perform entity_master_private.identity();if not exists(select 1 from entity_master_private.meta(k))or a not in('view','create','edit','delete')then return false;end if;if a='view'then return asset_posting_private.allowed('entities:'||k,'view');end if;return exists(select 1 from public.role_access_matrix m where m.role_id=public.app_active_role_id()and m.resource_key='entities:'||k and case a when'create'then m.can_create when'edit'then m.can_edit else m.can_delete end);exception when insufficient_privilege then return false;end$$;
create function entity_master_private.access(k text,a text)returns bigint language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$declare sid bigint:=entity_master_private.identity();begin if not entity_master_private.allowed(k,a)then raise exception using errcode='42501',message='Requiere permiso explícito de mantenimiento de la entidad.';end if;return sid;end$$;
create function entity_master_private.read_allowed(k text)returns boolean language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$begin perform entity_master_private.identity();return entity_master_private.allowed(k,'view');exception when insufficient_privilege then return false;end$$;
create function entity_master_private.visible(k text,id bigint)returns boolean language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$declare sid bigint:=entity_master_private.identity();begin return entity_master_private.read_allowed(k)and exists(select 1 from public.entity_subsidiaries s where s.subsidiary_id=sid and(case k when'customers'then s.customer_id else s.supplier_id end)=$2);exception when insufficient_privilege then return false;end$$;
create function entity_master_private.scope_ids(k text,id bigint)returns bigint[]language sql stable security definer set search_path=pg_catalog,public,pg_temp as $$select coalesce(array_agg(subsidiary_id order by is_primary desc,subsidiary_id),'{}'::bigint[])from public.entity_subsidiaries where(case k when'customers'then customer_id else supplier_id end)=$2$$;
create function entity_master_private.writable(k text,id bigint)returns boolean language sql stable security definer set search_path=pg_catalog,public,pg_temp as $$select not exists(select 1 from unnest(entity_master_private.scope_ids(k,id))s where not exists(select 1 from public.user_subsidiaries us where us.user_id=public.app_user_id()and us.subsidiary_id=s))$$;
create function entity_master_private.used(t text,id bigint)returns boolean language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$declare f record;b boolean;begin for f in select n.nspname,c.relname,a.attname,cardinality(co.conkey)len from pg_constraint co join pg_class c on c.oid=co.conrelid join pg_namespace n on n.oid=c.relnamespace join pg_attribute a on a.attrelid=c.oid and a.attnum=co.conkey[1]where co.contype='f'and co.confrelid=to_regclass('public.'||t)and c.relname not in('entity_subsidiaries','customer_currencies','supplier_currencies','entity_withholding_rules')loop if f.len<>1 then return true;end if;execute format('select exists(select 1 from %I.%I where %I=$1)',f.nspname,f.relname,f.attname)into b using id;if b then return true;end if;end loop;return false;end$$;
create function entity_master_private.fingerprint(k text,id bigint)returns text language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$declare c record;r jsonb;links jsonb;cur jsonb;rules jsonb;begin select *into c from entity_master_private.meta(k);execute format('select to_jsonb(x)from public.%I x where %I=$1',c.t,c.pk)into r using id;select coalesce(jsonb_agg(to_jsonb(x)order by x.subsidiary_id),'[]')into links from public.entity_subsidiaries x where(case k when'customers'then customer_id else supplier_id end)=$2;execute format('select coalesce(jsonb_agg(to_jsonb(x)order by currency_id),''[]'')from public.%I x where %I=$1',c.curtable,c.pk)into cur using id;select coalesce(jsonb_agg(to_jsonb(x)order by subsidiary_id,tax_code_id),'[]')into rules from public.entity_withholding_rules x where(case k when'customers'then customer_id else supplier_id end)=$2;return md5(jsonb_build_array(r,links,cur,rules)::text);end$$;
create function entity_master_private.dto(k text,id bigint)returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$declare c record;r jsonb;cur jsonb;rules jsonb;begin select *into c from entity_master_private.meta(k);execute format('select to_jsonb(x)from public.%I x where %I=$1',c.t,c.pk)into r using id;execute format('select coalesce(jsonb_agg(currency_id order by is_primary desc,currency_id),''[]'')from public.%I where %I=$1',c.curtable,c.pk)into cur using id;select coalesce(jsonb_agg(jsonb_build_object('subsidiary_id',x.subsidiary_id,'tax_code_id',x.tax_code_id)order by x.subsidiary_id,x.tax_code_id),'[]')into rules from public.entity_withholding_rules x where(case k when'customers'then customer_id else supplier_id end)=$2 and exists(select 1 from public.user_subsidiaries us where us.user_id=public.app_user_id()and us.subsidiary_id=x.subsidiary_id);
 return r||jsonb_build_object('subsidiary_ids',coalesce((select jsonb_agg(s order by n)from unnest(entity_master_private.scope_ids(k,id))with ordinality x(s,n)where exists(select 1 from public.user_subsidiaries us where us.user_id=public.app_user_id()and us.subsidiary_id=s)),'[]'),'currency_ids',cur,'withholding_rules',rules,'_revision',entity_master_private.fingerprint(k,id),'_actions',jsonb_build_object('canEdit',entity_master_private.allowed(k,'edit')and entity_master_private.writable(k,id),'canDelete',entity_master_private.allowed(k,'delete')and entity_master_private.writable(k,id)and not entity_master_private.used(c.t,id)));end$$;
create function entity_master_private.currency_ok(cid bigint,sid bigint)returns boolean language sql stable security definer set search_path=pg_catalog,public,pg_temp as $$select exists(select 1 from public.currencies where currency_id=cid)and(exists(select 1 from public.subsidiaries where subsidiary_id=sid and currency_id=cid)or exists(select 1 from public.subsidiary_currencies where subsidiary_id=sid and currency_id=cid))$$;
create function entity_master_private.ids(p jsonb)returns bigint[]language plpgsql immutable set search_path=pg_catalog as $$declare x jsonb;r bigint[];begin if jsonb_typeof(p)is distinct from'array'or jsonb_array_length(p)not between 1 and 200 then raise exception using errcode='22023',message='Seleccione entre una y doscientas asignaciones.';end if;for x in select value from jsonb_array_elements(p)loop if jsonb_typeof(x)not in('number','string')or(x#>>'{}')!~'^[1-9][0-9]{0,15}$'or(x#>>'{}')::numeric>9007199254740991 then raise exception using errcode='22023',message='Asignación inválida.';end if;end loop;select array_agg((value#>>'{}')::bigint)into r from jsonb_array_elements(p);if cardinality(r)<>(select count(distinct v)from unnest(r)v)then raise exception using errcode='22023',message='No repita asignaciones.';end if;return r;end$$;

create function public.entity_master_list(p_catalog text)returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$declare c record;r jsonb;begin perform entity_master_private.access(p_catalog,'view');select *into c from entity_master_private.meta(p_catalog);execute format('select coalesce(jsonb_agg(entity_master_private.dto($1,%I)order by %I),''[]'')from public.%I where entity_master_private.visible($1,%I)',c.pk,c.pk,c.t,c.pk)into r using p_catalog;return r;end$$;
create function public.entity_master_options(p_catalog text)returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$declare sid bigint:=entity_master_private.access(p_catalog,'view');begin return jsonb_build_object('canView',true,'canCreate',entity_master_private.allowed(p_catalog,'create'),'canEdit',entity_master_private.allowed(p_catalog,'edit'),'canDelete',entity_master_private.allowed(p_catalog,'delete'),'references',jsonb_build_object(
 'organization/subsidiaries',coalesce((select jsonb_agg(jsonb_build_object('subsidiary_id',s.subsidiary_id,'name',s.name,'country_id',s.country_id,'currency_id',s.currency_id))from public.subsidiaries s join public.user_subsidiaries us using(subsidiary_id)where us.user_id=public.app_user_id()and s.is_active),'[]'),
 'core/currencies',coalesce((select jsonb_agg(to_jsonb(c))from public.currencies c where exists(select 1 from public.user_subsidiaries us join public.subsidiaries s using(subsidiary_id)where us.user_id=public.app_user_id()and s.is_active and entity_master_private.currency_ok(c.currency_id,s.subsidiary_id))),'[]'),
 'core/countries',coalesce((select jsonb_agg(to_jsonb(c))from public.countries c),'[]'),
 'configuration/payment-terms',coalesce((select jsonb_agg(to_jsonb(x))from public.payment_terms x),'[]'),
 'banking/banks',coalesce((select jsonb_agg(to_jsonb(x))from public.banks x),'[]'),
 'organization/departments',coalesce((select jsonb_agg(to_jsonb(d))from public.departments d where d.type='Cliente'and not d.is_inactive and exists(select 1 from public.user_subsidiaries us where us.user_id=public.app_user_id()and(us.subsidiary_id=d.subsidiary_id or exists(select 1 from public.department_subsidiaries x where x.department_id=d.department_id and x.subsidiary_id=us.subsidiary_id)))),'[]'),
 'entities/employees',coalesce((select jsonb_agg(jsonb_build_object('employee_id',e.employee_id,'first_name',e.first_name,'last_name',e.last_name,'is_sales_representative',e.is_sales_representative,'subsidiary_id',e.subsidiary_id))from public.employees e join public.user_subsidiaries us using(subsidiary_id)where us.user_id=public.app_user_id()and e.is_active and e.is_sales_representative),'[]'),
 'configuration/tax-codes',coalesce((select jsonb_agg(to_jsonb(tc)||jsonb_build_object('tax_type_applies_to',tt.applies_to,'subsidiary_ids',coalesce((select jsonb_agg(cs.subsidiary_id)from public.tax_code_subsidiaries cs join public.user_subsidiaries us using(subsidiary_id)join public.subsidiaries s using(subsidiary_id)where cs.tax_code_id=tc.tax_code_id and us.user_id=public.app_user_id()and s.is_active and s.country_id=tc.country_id),'[]')))from public.tax_codes tc join public.tax_types tt using(tax_type_id)where tc.is_withholding and tt.applies_to in(case when p_catalog='customers'then'Ventas'else'Compras'end,'Ambos')and exists(select 1 from public.tax_code_subsidiaries cs join public.user_subsidiaries us using(subsidiary_id)join public.subsidiaries s using(subsidiary_id)where cs.tax_code_id=tc.tax_code_id and us.user_id=public.app_user_id()and s.is_active and s.country_id=tc.country_id)),'[]')));end$$;

create function public.save_entity_master(p_catalog text,p_payload jsonb,p_id bigint default null)returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare c record;sid bigint;oldrow jsonb;data jsonb;typed jsonb;subs bigint[];curs bigint[];oldcurs bigint[];oldsubs bigint[];rules jsonb;rule jsonb;k text;pid bigint;cols text;vals text;sets text;n int;affected int;sub bigint;cur bigint;rsid bigint;tax bigint;credit numeric;used boolean;iban text;begin
 sid:=entity_master_private.access(p_catalog,case when p_id is null then'create'else'edit'end);select *into c from entity_master_private.meta(p_catalog);if p_id<=0 or jsonb_typeof(p_payload)is distinct from'object'or pg_column_size(p_payload)>64000 or exists(select 1 from jsonb_object_keys(p_payload)x where not x=any(c.fields||array['subsidiary_ids','currency_ids','withholding_rules','_revision']))then raise exception using errcode='22023',message='Campos de entidad inválidos.';end if;
 perform pg_advisory_xact_lock(793145,1);
 if p_id is not null then execute format('select to_jsonb(x)from public.%I x where %I=$1 for update',c.t,c.pk)into oldrow using p_id;if oldrow is null or not entity_master_private.visible(p_catalog,p_id)or not entity_master_private.writable(p_catalog,p_id)then raise exception using errcode='42501',message='Entidad compartida no disponible para mantenimiento.';end if;if p_payload->>'_revision'is distinct from entity_master_private.fingerprint(p_catalog,p_id)then raise exception using errcode='55000',message='La entidad cambió. Consúltela nuevamente.';end if;end if;
 subs:=entity_master_private.ids(p_payload->'subsidiary_ids');curs:=entity_master_private.ids(p_payload->'currency_ids');
 if not sid=any(subs)or exists(select 1 from unnest(subs)x where not exists(select 1 from public.user_subsidiaries us join public.subsidiaries s using(subsidiary_id)where us.user_id=public.app_user_id()and s.subsidiary_id=x and s.is_active))then raise exception using errcode='42501',message='Seleccione subsidiarias activas autorizadas incluyendo la actual.';end if;
 if not entity_master_private.currency_ok(curs[1],subs[1])or exists(select 1 from unnest(curs)x where not exists(select 1 from unnest(subs)y where entity_master_private.currency_ok(x,y)))or exists(select 1 from unnest(subs)y where not exists(select 1 from unnest(curs)x where entity_master_private.currency_ok(x,y)))then raise exception using errcode='42501',message='Las monedas deben estar disponibles para las subsidiarias seleccionadas.';end if;
 data:=coalesce(oldrow,jsonb_build_object('is_intercompany',false,'applies_withholding',false,'credit_limit',0,'envio_estado_cuenta_auto',false))||(p_payload-'subsidiary_ids'-'currency_ids'-'withholding_rules'-'_revision');
 foreach k in array c.fields loop if jsonb_typeof(data->k)='string'then data:=jsonb_set(data,array[k],to_jsonb(btrim(data->>k)));end if;if data->>k=''then data:=jsonb_set(data,array[k],'null');end if;if k in('is_intercompany','applies_withholding','envio_estado_cuenta_auto')and data?k and jsonb_typeof(data->k)is distinct from'boolean'then raise exception using errcode='22023',message='Las opciones de la entidad deben ser booleanas.';end if;end loop;
 if p_catalog='suppliers'and data->>'payment_iban'is not null then iban:=upper(regexp_replace(data->>'payment_iban','\s','','g'));if iban!~'^CR[0-9]{20}$'then raise exception using errcode='22023',message='IBAN para pagos inválido.';end if;data:=data||jsonb_build_object('payment_iban',iban);end if;
 data:=data||jsonb_build_object('primary_subsidiary_id',subs[1],'currency_id',curs[1]);execute format('select to_jsonb(jsonb_populate_record(null::public.%I,$1))',c.t)into typed using data;data:=typed;
 if nullif(trim(data->>'company_name'),'')is null or length(data->>'company_name')>250 or nullif(trim(data->>'tax_id'),'')is null or length(data->>'tax_id')>80 or coalesce(data->>(case when p_catalog='customers'then'customer_type'else'supplier_type'end),'')not in('Empresa','Personal')then raise exception using errcode='22023',message='Revise nombre, identificación y tipo de entidad.';end if;
 if data->>'email'is not null and(length(data->>'email')>254 or data->>'email'!~'^[^[:space:]@,;<>]+@[^[:space:]@,;<>]+\.[^[:space:]@,;<>]+$')then raise exception using errcode='22023',message='Correo electrónico inválido.';end if;
 if length(coalesce(data->>'address',''))>4000 or length(coalesce(data->>'comments',''))>8000 or length(coalesce(data->>'phone',''))>80 then raise exception using errcode='22023',message='Datos de contacto demasiado largos.';end if;
 if data->>'payment_term_id'is not null and not exists(select 1 from public.payment_terms where term_id=(data->>'payment_term_id')::bigint)then raise exception using errcode='42501',message='Término de pago no disponible.';end if;
 if p_catalog='customers'then credit:=(data->>'credit_limit')::numeric;if not asset_posting_private.finite(credit)or credit<0 or credit>=1e18 then raise exception using errcode='22023',message='Límite de crédito inválido.';end if;
 if(data->>'envio_estado_cuenta_auto')::boolean and data->>'email'is null then raise exception using errcode='22023',message='Configure el correo para el estado de cuenta.';end if;
 if data->>'country_id'is not null and not exists(select 1 from public.countries where country_id=(data->>'country_id')::bigint)then raise exception using errcode='42501',message='País no disponible.';end if;
 if data->>'department_id'is not null and not exists(select 1 from public.departments d where d.department_id=(data->>'department_id')::bigint and d.type='Cliente'and not d.is_inactive and(d.subsidiary_id=subs[1]or exists(select 1 from public.department_subsidiaries ds where ds.department_id=d.department_id and ds.subsidiary_id=subs[1])))then raise exception using errcode='42501',message='Departamento de cliente no disponible.';end if;
 if data->>'sales_representative_id'is not null and not exists(select 1 from public.employees where employee_id=(data->>'sales_representative_id')::bigint and is_active and is_sales_representative and subsidiary_id=subs[1])then raise exception using errcode='42501',message='Representante de ventas no disponible.';end if;
 else credit:=0;if data->>'payment_id_type'is not null and data->>'payment_id_type'not in('F','J','DIMEX','NITE')then raise exception using errcode='22023',message='Tipo de identificación bancaria inválido.';end if;
 if data->>'payment_bank_id'is not null and not exists(select 1 from public.banks where bank_id=(data->>'payment_bank_id')::bigint)then raise exception using errcode='42501',message='Banco no disponible.';end if;
 iban:=upper(regexp_replace(coalesce(data->>'payment_iban',''),'\s','','g'));if iban<>''then if iban!~'^CR[0-9]{20}$'or mod((substr(iban,5)||'1227'||substr(iban,3,2))::numeric,97)<>1 then raise exception using errcode='22023',message='IBAN para pagos inválido.';end if;data:=data||jsonb_build_object('payment_iban',iban);end if;
 end if;
 rules:=coalesce(p_payload->'withholding_rules','[]');if jsonb_typeof(rules)is distinct from'array'or jsonb_array_length(rules)>400 then raise exception using errcode='22023',message='Reglas de retención inválidas.';end if;
 if(data->>'applies_withholding')::boolean is distinct from(jsonb_array_length(rules)>0)then raise exception using errcode='22023',message='Active retenciones y defina al menos una regla, o desactive y quite las reglas.';end if;
 if(select count(*)from jsonb_array_elements(rules))<>(select count(distinct jsonb_build_array((x->>'subsidiary_id')::bigint,(x->>'tax_code_id')::bigint))from jsonb_array_elements(rules)x)then raise exception using errcode='22023',message='No repita reglas de retención.';end if;
 for rule in select value from jsonb_array_elements(rules)loop
  if jsonb_typeof(rule)is distinct from'object'or exists(select 1 from jsonb_object_keys(rule)x where x not in('subsidiary_id','tax_code_id'))then raise exception using errcode='22023',message='Campos de regla de retención inválidos.';end if;
  rsid:=(rule->>'subsidiary_id')::bigint;tax:=(rule->>'tax_code_id')::bigint;
  if rsid is null or not rsid=any(subs)or not exists(select 1 from public.tax_codes tc join public.tax_types tt using(tax_type_id)join public.tax_code_subsidiaries cs using(tax_code_id)join public.subsidiaries s on s.subsidiary_id=cs.subsidiary_id where tc.tax_code_id=tax and cs.subsidiary_id=rsid and tc.country_id=s.country_id and tt.country_id=tc.country_id and tc.is_withholding and tt.applies_to in(case when p_catalog='customers'then'Ventas'else'Compras'end,'Ambos')and asset_posting_private.finite(tc.rate_percentage)and tc.rate_percentage between 0 and 100 and tc.withholding_calculation_base in('Subtotal antes de impuestos','Importe de impuestos','Total de la factura con impuestos')and tc.withholding_application_moment in('Al registrar la factura','Al aplicar el pago')and(case when p_catalog='customers'then tt.asset_account_id else tt.liability_account_id end)is not null)then raise exception using errcode='42501',message='Retención no disponible para la entidad y subsidiaria seleccionadas.';end if;
  perform tax_catalog_private.account((select case when p_catalog='customers'then tt.asset_account_id else tt.liability_account_id end from public.tax_codes tc join public.tax_types tt using(tax_type_id)where tc.tax_code_id=tax),case when p_catalog='customers'then'Activo'else'Pasivo'end,array[rsid]);
 end loop;
 if p_id is not null then oldsubs:=entity_master_private.scope_ids(p_catalog,p_id);execute format('select array_agg(currency_id)from public.%I where %I=$1',c.curtable,c.pk)into oldcurs using p_id;used:=entity_master_private.used(c.t,p_id);if used and(not oldsubs<@subs or not coalesce(oldcurs,'{}'::bigint[])<@curs)then raise exception using errcode='55000',message='La entidad utilizada conserva sus subsidiarias y monedas existentes.';end if;end if;
 select string_agg(format('%I',x),','),string_agg(format('r.%I',x),','),string_agg(format('%I=r.%I',x,x),',')into cols,vals,sets from unnest(c.fields||array['primary_subsidiary_id','currency_id'])x;
 if p_id is null then execute format('insert into public.%I(%s)select %s from jsonb_populate_record(null::public.%I,$1)r returning %I',c.t,cols,vals,c.t,c.pk)into pid using data;else pid:=p_id;execute format('update public.%I x set %s from jsonb_populate_record(null::public.%I,$1)r where x.%I=$2',c.t,sets,c.t,c.pk)using data,pid;end if;
 execute format('delete from public.entity_subsidiaries where %I=$1 and not(subsidiary_id=any($2))',c.pk)using pid,subs;execute format('update public.entity_subsidiaries set is_primary=false where %I=$1',c.pk)using pid;
 n:=0;foreach sub in array subs loop n:=n+1;execute format('update public.entity_subsidiaries set is_primary=$3,credit_limit=case when $4 then $5 else credit_limit end where %I=$1 and subsidiary_id=$2',c.pk)using pid,sub,n=1,p_id is null or (data->'credit_limit'is distinct from oldrow->'credit_limit'),credit;get diagnostics affected = row_count;
 if affected=0 then execute format('insert into public.entity_subsidiaries(%I,subsidiary_id,is_primary,credit_limit)values($1,$2,$3,$4)',c.pk)using pid,sub,n=1,credit;end if;end loop;
 execute format('delete from public.%I where %I=$1 and not(currency_id=any($2))',c.curtable,c.pk)using pid,curs;execute format('update public.%I set is_primary=false where %I=$1',c.curtable,c.pk)using pid;n:=0;
 foreach cur in array curs loop n:=n+1;execute format('update public.%I set is_primary=$3 where %I=$1 and currency_id=$2',c.curtable,c.pk)using pid,cur,n=1;get diagnostics affected=row_count;if affected=0 then execute format('insert into public.%I(%I,currency_id,is_primary)values($1,$2,$3)',c.curtable,c.pk)using pid,cur,n=1;end if;end loop;
 execute format('delete from public.entity_withholding_rules x where %I=$1 and not exists(select 1 from jsonb_array_elements($2)r where(r->>''subsidiary_id'')::bigint=x.subsidiary_id and(r->>''tax_code_id'')::bigint=x.tax_code_id)',c.pk)using pid,rules;
 for rule in select value from jsonb_array_elements(rules)loop execute format('insert into public.entity_withholding_rules(%I,subsidiary_id,tax_code_id)select $1,$2,$3 where not exists(select 1 from public.entity_withholding_rules where %I=$1 and subsidiary_id=$2 and tax_code_id=$3)',c.pk,c.pk)using pid,(rule->>'subsidiary_id')::bigint,(rule->>'tax_code_id')::bigint;end loop;
 return entity_master_private.dto(p_catalog,pid);end$$;
create function public.delete_entity_master(p_catalog text,p_id bigint,p_revision text default null)returns boolean language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare c record;r jsonb;begin perform entity_master_private.access(p_catalog,'delete');perform pg_advisory_xact_lock(793145,1);select *into c from entity_master_private.meta(p_catalog);if p_id is null or p_id<=0 then raise exception using errcode='22023',message='Entidad inválida.';end if;execute format('select to_jsonb(x)from public.%I x where %I=$1 for update',c.t,c.pk)into r using p_id;
 if r is null or not entity_master_private.visible(p_catalog,p_id)or not entity_master_private.writable(p_catalog,p_id)then raise exception using errcode='42501',message='Entidad no disponible para eliminar.';end if;if p_revision is distinct from entity_master_private.fingerprint(p_catalog,p_id)or entity_master_private.used(c.t,p_id)then raise exception using errcode='55000',message='La entidad cambió o tiene referencias.';end if;execute format('delete from public.%I where %I=$1',c.t,c.pk)using p_id;return true;end$$;
alter function public.entity_catalog_export_data(text,text)set schema entity_master_private;
create function public.entity_catalog_export_data(p_catalog text,p_search text default'')returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$begin perform entity_master_private.identity();if p_catalog in('customers','suppliers')then perform entity_master_private.access(p_catalog,'view');end if;return entity_master_private.entity_catalog_export_data(p_catalog,p_search);end$$;
do $$declare t text;p record;c record;pred text;begin foreach t in array array['customers','suppliers','entity_subsidiaries','customer_currencies','supplier_currencies','entity_withholding_rules']loop
 execute format('alter table public.%I enable row level security',t);for p in select policyname from pg_policies where schemaname='public'and tablename=t loop execute format('drop policy %I on public.%I',p.policyname,t);end loop;execute format('revoke all on public.%I from public,anon,authenticated,service_role',t);for c in select column_name from information_schema.columns where table_schema='public'and table_name=t loop execute format('revoke insert(%I),update(%I),select(%I),references(%I)on public.%I from public,anon,authenticated,service_role',c.column_name,c.column_name,c.column_name,c.column_name,t);end loop;
 pred:=case t when'customers'then'entity_master_private.visible(''customers'',customer_id)'when'suppliers'then'entity_master_private.visible(''suppliers'',supplier_id)'when'customer_currencies'then'entity_master_private.visible(''customers'',customer_id)'when'supplier_currencies'then'entity_master_private.visible(''suppliers'',supplier_id)'else'subsidiary_id=public.active_subsidiary_id()and((customer_id is not null and entity_master_private.visible(''customers'',customer_id))or(supplier_id is not null and entity_master_private.visible(''suppliers'',supplier_id)))'end;
 execute format('create policy entity_master_read on public.%I for select to authenticated using(%s)',t,pred);execute format('grant select on public.%I to authenticated',t);end loop;end$$;
revoke all on all functions in schema entity_master_private from public,anon,authenticated,service_role;grant execute on function entity_master_private.visible(text,bigint)to authenticated;
revoke all on function public.entity_master_list(text),public.entity_master_options(text),public.save_entity_master(text,jsonb,bigint),public.delete_entity_master(text,bigint,text),public.entity_catalog_export_data(text,text)from public,anon,authenticated,service_role;
grant execute on function public.entity_master_list(text),public.entity_master_options(text),public.save_entity_master(text,jsonb,bigint),public.delete_entity_master(text,bigint,text),public.entity_catalog_export_data(text,text)to authenticated;
-- Suppliers have no is_inactive column in the deployed schema. Preserve the
-- existing scope check, using the same optional-column convention as sales.
do $$declare source text;begin
 source:=pg_get_functiondef('supplier_invoice_private.prepare_before_receipt(jsonb,bigint)'::regprocedure);
 if position('and not s.is_inactive' in source)=0 then raise exception 'Unexpected supplier invoice guard definition';end if;
 execute replace(source,'and not s.is_inactive','and not coalesce((to_jsonb(s)->>''is_inactive'')::boolean,false)');
end$$;
notify pgrst,'reload schema';
